    var expected = crypto.createHmac('sha256', secret).update(payloadB64).digest('hex');
    if (sig !== expected) return null;
    var payload = JSON.parse(Buffer.from(payloadB64, 'base64').toString());
    if (payload.exp < Date.now()) return null;
    return payload;
